import { computed, defineComponent, h, type PropType } from 'vue';
import { emptyStyleKeys, getEmptyMediaVariantKey } from '../lib/core';
import type { EmptyMediaVariant } from '../lib/core';
import styles from './empty.module.scss';

export const Empty = defineComponent({
	name: 'Empty',
	setup(_props, { slots, attrs }) {
		return () => h('div', { ...attrs, 'data-slot': 'empty', class: [styles[emptyStyleKeys.root], attrs.class] }, slots.default?.());
	},
});

export const EmptyHeader = defineComponent({
	name: 'EmptyHeader',
	setup(_props, { slots, attrs }) {
		return () => h('div', { ...attrs, 'data-slot': 'empty-header', class: [styles[emptyStyleKeys.header], attrs.class] }, slots.default?.());
	},
});

export const EmptyMedia = defineComponent({
	name: 'EmptyMedia',
	props: {
		variant: {
			type: String as PropType<EmptyMediaVariant>,
			default: 'default',
		},
	},
	setup(props, { slots, attrs }) {
		const variantKey = computed(() => getEmptyMediaVariantKey(props.variant));
		const classes = computed(() => [styles[emptyStyleKeys.media], styles[variantKey.value], attrs.class]);

		return () => h('div', { ...attrs, 'data-slot': 'empty-icon', 'data-variant': props.variant, class: classes.value }, slots.default?.());
	},
});

export const EmptyTitle = defineComponent({
	name: 'EmptyTitle',
	setup(_props, { slots, attrs }) {
		return () => h('div', { ...attrs, 'data-slot': 'empty-title', class: [styles[emptyStyleKeys.title], attrs.class] }, slots.default?.());
	},
});

export const EmptyDescription = defineComponent({
	name: 'EmptyDescription',
	setup(_props, { slots, attrs }) {
		return () => h('div', { ...attrs, 'data-slot': 'empty-description', class: [styles[emptyStyleKeys.description], attrs.class] }, slots.default?.());
	},
});

export const EmptyContent = defineComponent({
	name: 'EmptyContent',
	setup(_props, { slots, attrs }) {
		return () => h('div', { ...attrs, 'data-slot': 'empty-content', class: [styles[emptyStyleKeys.content], attrs.class] }, slots.default?.());
	},
});

export default Empty;

@use '../../../styles/variables/colors' as *;

// Empty 根容器
.root {
	display: flex;
	min-width: 0;
	flex: 1;
	flex-direction: column;
	align-items: center;
	justify-content: center;
	gap: $spacing-6;
	border-radius: var(--tile-empty-radius, $radius);
	border: 1px var(--tile-empty-border-style, dashed) var(--tile-empty-border, $border);
	background-color: var(--tile-empty-background, transparent);
	padding: var(--tile-empty-padding, $spacing-6);
	text-align: center;
	text-wrap: balance;

	// 大屏加深内边距
	@media (min-width: 768px) {
		padding: var(--tile-empty-padding, $spacing-12);
	}
}

// 头部：媒体 + 标题 + 描述
.header {
	display: flex;
	max-width: 24rem;
	flex-direction: column;
	align-items: center;
	gap: var(--tile-empty-header-gap, $spacing-2);
	text-align: center;
}

// 媒体区（图标容器）
.media {
	display: flex;
	flex-shrink: 0;
	align-items: center;
	justify-content: center;
	margin-bottom: $spacing-2;

	svg {
		pointer-events: none;
		flex-shrink: 0;
	}

	// 变体
	&.variantDefault {
		background-color: transparent;
	}

	&.variantIcon {
		width: $spacing-10;
		height: $spacing-10;
		border-radius: $radius;
		background-color: var(--tile-empty-media-background, $muted);
		color: $foreground;

		svg {
			width: $spacing-6;
			height: $spacing-6;
		}
	}
}

// 标题
.title {
	font-size: var(--tile-empty-title-size, $text-lg);
	font-weight: var(--tile-empty-title-weight, $font-medium);
	letter-spacing: var(--tile-empty-title-tracking, -0.01em);
}

// 描述
.description {
	font-size: var(--tile-empty-description-size, $text-sm);
	line-height: var(--tile-empty-description-leading, $leading-relaxed);
	color: var(--tile-empty-description-color, $muted-foreground);

	a {
		text-decoration: underline;
		text-underline-offset: 4px;
	}

	a:hover {
		color: $primary;
	}
}

// 内容区（操作按钮等）
.content {
	display: flex;
	width: 100%;
	max-width: 24rem;
	min-width: 0;
	flex-direction: column;
	align-items: center;
	gap: $spacing-4;
	font-size: $text-sm;
	text-wrap: balance;
}
